from flask import Flask, redirect, url_for, session
from flask_dance.contrib.github import make_github_blueprint, github

app = Flask(__name__)
app.secret_key = "supersekrit"  # Used to sign the session cookie

# Create and register the GitHub OAuth blueprint
github_bp = make_github_blueprint(
    client_id="YOUR_CLIENT_ID", client_secret="YOUR_CLIENT_SECRET",
    scope="user", redirect_url="http://localhost:5000/github-callback"
)
app.register_blueprint(github_bp, url_prefix="/github")

# Route to start the GitHub OAuth flow
@app.route("/github-login")
def github_login():
    if not github.authorized:
        return redirect(url_for("github.login"))
    return "You are now logged in with GitHub."

# Route to handle the GitHub OAuth callback
@app.route("/github-callback")
def github_callback():
    if not github.authorized:
        return redirect(url_for("github.login"))
    # Get the GitHub OAuth token
    token = github.get_access_token()
    session["token"] = token
    return redirect(url_for("get_token"))

# Route to retrieve the access token from the session
@app.route("/get-token")
def get_token():
    token = session.get("token")
    if token:
        return {"access_token": token["access_token"], "token": token}
    return "Token not found in session."

if __name__ == "__main__":
    app.run(debug=True)
end_of_edit

