def _pad(s, l):
    """
    Pads *s* to length *l*.
    """
    missing = l - len(s)
    print(f"_pad called with s={s} and l={l}")  # log the arguments
    if isinstance(s, dict):
        return str(s)
    return s + " " * (missing if missing > 0 else 0)
