    def factor(cls, rule, target, rounding="nearest"):
        """
        The factor rule multiplies the value by a factor and specifies the rounding direction.
        """
        value = cls._dot_reduce(rule['from'], target)
        original_type = type(value)
        if rounding == "up":
            return original_type(Decimal(value) * Decimal(rule['factor']).ceil())
        elif rounding == "down":
            return original_type(Decimal(value) * Decimal(rule['factor']).floor())
        else:
            return original_type(Decimal(value) * Decimal(rule['factor']).round())
