class SimpleSchema:
    def __init__(self, key, fields):
        self._key = key
        self._fields = fields

    def _get_field(self, key):
        return self._fields.get(key)

class TestNetworkField(Config):
    def __init__(self, schema=None):
        super().__init__(schema)
        self.network_field = IPv4NetworkField(min_prefix_length=10, max_prefix_length=20)

def test_network_field():
    config = TestNetworkField(schema=SimpleSchema('test', {'network_field': IPv4NetworkField()}))
    config.network_field = "192.168.0.0/16"  # Valid network
    assert config.network_field == "192.168.0.0/16"

    config.network_field = "192.168.0.0/8"  # Invalid network (too short)
    assert config.network_field == "192.168.0.0/8"

    config.network_field = "192.168.0.0/24"  # Invalid network (too long)
    assert config.network_field == "192.168.0.0/24"

if __name__ == "__main__":
    test_network_field()
    print("Script completed successfully, no errors.")
end_of_edit

