            return super().__new__(cls, backing=backing, hook=hook, **kwargs)

        input_nodes = []
        for i, (fkey, ftyp) in enumerate(cls.fields().items()):
            fnode: Node
            if fkey in kwargs:
                finput = kwargs.pop(fkey)
                if isinstance(finput, View):
                    fnode = finput.get_backing()
                else:
                    fnode = ftyp.coerce_view(finput).get_backing()
            else:
                fnode = ftyp.default_node()
            input_nodes.append(fnode)

        # Check for invalid field names
        defined_fields = set(cls.fields().keys())
        provided_fields = set(kwargs.keys())
        invalid_fields = provided_fields - defined_fields
