def make_constant(value):
    """Convert value to Pattern constant, best effort attempt
    at determining root value type and corresponding conversion

    Args:
        value: value to convert to Pattern constant
    """
    if isinstance(value, _Constant):
        return value

    try:
        # Attempt to parse the value as a datetime object
        value_as_datetime = parse_into_datetime(value)
        # If successful, create a TimestampConstant from it
        if isinstance(value_as_datetime, datetime.datetime):
            return TimestampConstant(value_as_datetime)
        # Otherwise, continue with the existing logic
        return value_as_datetime
    except (ValueError, TypeError):
        pass

    if isinstance(value, str):
        return StringConstant(value)
    elif isinstance(value, bool):
        return BooleanConstant(value)
    elif isinstance(value, int):
        return IntegerConstant(value)
    elif isinstance(value, float):
        return FloatConstant(value)
    elif isinstance(value, list):
        return ListConstant(value)
    else:
        raise ValueError("Unable to create a constant from %s" % value)
end_of_edit

