                    if not parts:
                        continue
                    cur_dir = "/".join(parts[:2])

                    # A few heuristics to get better reviewers
                    if cur_dir.startswith('compiler/'):
                        cur_dir = 'compiler'
                    if cur_dir == 'src/test':
                        cur_dir = None
                    if cur_dir and cur_dir not in counts:
                        counts[cur_dir] = 0
                    continue

                if cur_dir and (not line.startswith('+++')) and line.startswith('+'):
                    counts[cur_dir] += 1

            # Find the largest count.
            most_changes = 0
            for directory, changes in counts.items():
                if changes > most_changes:
                    most_changes = changes
                    most_changed = directory

        # lookup that directory in the json file to find the potential reviewers
        potential = groups['all']
        if most_changed and most_changed in dirs:
            potential.extend(dirs[most_changed])
        if not potential:
            potential = groups['core']

        # expand the reviewers list by group
        for name, people in groups.items():
            if name == 'all' or name == 'core':
                continue
            if exclude and name in exclude:
                continue
            potential.extend(people)

        # remove duplicates
        potential = list(set(potential))

        # Check if the review type is r? and assign a random reviewer if so
        if repo.endswith("rust-lang/docs") and diff.startswith("r? @"):
            reviewer = random.choice(potential)
            self.set_assignee(reviewer, owner, repo, issue, user, author, to_mention)
            return reviewer

        # Find the reviewer
        if 'msg' in locals() and msg is not None:
            match = reviewer_re.search(msg)
            reviewer = match.group(1) if match else None
        else:
            reviewer = None
        return reviewer
end_of_edit

