class CmdAdd(CmdBase):
    def run(self):
        try:
            if len(self.args.targets) > 1 and self.args.file:
                raise RecursiveAddingWhileUsingFilename()

            # Convert absolute paths to relative paths if they are within the repository
            targets = [self.repo.make_relative(t) for t in self.args.targets]

            self.repo.add(
                targets,
                recursive=self.args.recursive,
                no_commit=self.args.no_commit,
                fname=self.args.file,
            )

        except DvcException:
            logger.exception("")
            return 1
        return 0
