from cabinetry.model_utils import prefit_uncertainties
from pyhf.pdf import Model

def test_prefit_uncertainties():
    # Create a Model with a partially fixed parameter
    model = Model({
        "channels": ["channel1"],
        "parameters": ["param1"],
        "observations": [10],
        "modifiers": {
            "param1": {
                "type": "normsys",
                "data": [1, 2, 3],
                "suggested_fixed": [True, False, True]
            }
        }
    })

    # Calculate pre-fit uncertainties
    uncertainties = prefit_uncertainties(model)

    # Check if the uncertainties are correct
    assert uncertainties.tolist() == [0, 2, 0]

    print("Test completed successfully, no errors.")

if __name__ == "__main__":
    test_prefit_uncertainties()
end_of_edit

