import yaml

def load_yaml(file_path):
    with open(file_path, 'r') as f:
        return yaml.safe_load(f)

def interpolate_variables(data, params):
    for key, value in data.items():
        if isinstance(value, str):
            if '${' in value and '}' in value:
                for param_key, param_value in params.items():
                    value = value.replace('${' + param_key + '}', str(param_value))
                data[key] = value
        elif isinstance(value, dict):
            data[key] = interpolate_variables(value, params)
        elif isinstance(value, list):
            for i, item in enumerate(value):
                if isinstance(item, str):
                    if '${' in item and '}' in item:
                        for param_key, param_value in params.items():
                            value[i] = value[i].replace('${' + param_key + '}', str(param_value))
                elif isinstance(item, dict):
                    value[i] = interpolate_variables(item, params)
    return data

params = load_yaml('params.yaml')
dvc = load_yaml('dvc.yaml')

print("Params:")
print(params)

print("\nDVC:")
print(dvc)

# Test nested interpolation
print("\nTesting nested interpolation:")
interpolated_dvc = interpolate_variables(dvc, params)
print(interpolated_dvc)
end_of_edit

