from collections import deque

def load_yaml(file_path):
    with open(file_path, 'r') as f:
        return yaml.safe_load(f)

def interpolate_variables(data, params):
    queue = deque([data])
    seen = set()
    graph = {}

    def build_graph(value):
        if isinstance(value, dict):
            for key, val in value.items():
                if id(value) not in graph:
                    graph[id(value)] = []
                graph[id(value)].append(id(val))
                build_graph(val)
        elif isinstance(value, list):
            for item in value:
                if id(value) not in graph:
                    graph[id(value)] = []
                graph[id(value)].append(id(item))
                build_graph(item)

    def traverse_graph():
        while queue:
            value = queue.popleft()
            if id(value) in seen:
                continue
            seen.add(id(value))

            if isinstance(value, str):
                while '${' in value and '}' in value:
                    for param_key, param_value in params.items():
                        if isinstance(param_value, str):
                            value = value.replace('${' + param_key + '}', param_value)
                        elif isinstance(param_value, dict):
                            for nested_key, nested_value in param_value.items():
                                value = value.replace('${' + param_key + '.' + nested_key + '}', str(nested_value))
            elif isinstance(value, dict):
                for key, val in value.items():
                    queue.append(val)
            elif isinstance(value, list):
                for item in value:
                    queue.append(item)

    build_graph(data)
    traverse_graph()

    return data

