class PrefixFixedEnvSettingsSource(EnvSettingsSource):
    def explode_env_vars(
        self, field: ModelField, env_vars: Mapping[str, Optional[str]]
    ) -> Dict[str, Any]:
        """
        Fix original explode_env_vars which splits the prefix with
        env_nested_delimiter. This implemetation doesn't split the prefix.
        """
        prefixes = [
            f"{env_name}{self.env_nested_delimiter}"
            for env_name in field.field_info.extra["env_names"]
        ]
        result: Dict[str, Any] = {}
        for env_name, env_val in env_vars.items():
            matching_prefixes = [
                prefix for prefix in prefixes if env_name.startswith(prefix)
            ]
            if not matching_prefixes:
                continue
            longest_prefix = max(len(prefix) for prefix in matching_prefixes)
            *keys, last_key = env_name[longest_prefix:].split(self.env_nested_delimiter)
            env_var = result
            for key in keys:
                env_var = env_var.setdefault(key, {})
            env_var[last_key] = env_val

        return result
end_of_edit

