import ckanapi

def get_organization(portal_url, organization_name_or_id):
    ckan = ckanapi.RemoteCKAN(portal_url)
    try:
        organization = ckan.action.organization_show(id=organization_name_or_id)
        return organization
    except ckanapi.errors.CKANAPIError as e:
        print(f"Error: {e}")
        return None

