    def ANNASSIGN(self, node):
        target = node.target
        annotation = node.annotation
        value = node.value

        # Check if the target is a valid name
        if isinstance(target, ast.Name):
            name = target.id

            # Check if the name is undefined
            if name not in self.scope:
                self.report(messages.UndefinedName, target, name)

            # Handle the annotation
            self.handleAnnotation(annotation, node)

            # If the assignment has a value, handle it now
            if value:
                # If the annotation is `TypeAlias`, handle the value as an annotation
                if _is_typing(annotation, 'TypeAlias', self.scopeStack):
                    self.handleAnnotation(value, node)
                else:
                    self.handleNode(value, node)
        else:
            self.handleNode(target, node)
            self.handleAnnotation(annotation, node)
            if value:
                self.handleNode(value, node)
