    @classmethod
    def factor(cls, rule, target):
        """
        The factor rule multiplies the value by a factor.
        """
        value = cls._dot_reduce(rule['from'], target)
        original_type = type(value)
        if 'rounding' in rule:
            rounding = rule['rounding']
        else:
            rounding = 'nearest'
        return original_type(Decimal(value) * Decimal(rule['factor'])).quantize(Decimal('1'), rounding=rounding)
