    @staticmethod
    def _get_data_format_3(raw):
        """
        Validate that data is from RuuviTag and is Data Format 3

        Returns:
            string: Sensor data
        """
        try:
            # Remove extra NULL bytes
            raw = raw.rstrip(b'\x00')

            if len(raw) != 54:
                return None

            if raw[16:18] != b'03':
                return None

            return raw[16:]
        except:
            return None
end_of_edit

